"""
    Find a key in the wkt, return it's name and items.

    .. versionadded:: 9.2
    """
def find_key(wkt: Any, k: Any) -> object {
    for w in wkt {
        if (`type(w) is `dict) {
            if (w['key'] == k) {
                return (w['name'], w.get('items', []));
            }
            (name, items) = find_key(w.get('items', []), k);
            if name {
                return (name, items);
            }
        }
    }
    return ('', []);
}

