def find_key(wkt, k):
    """
    Find a key in the wkt, return it's name and items.

    .. versionadded:: 9.2
    """

    for w in wkt:
        if type(w) is dict:
            if w['key'] == k:
                return w['name'], w.get('items', [])

            # try the kids
            name, items = find_key(w.get('items', []), k)
            if name:
                return name, items

    return '', []

