"""convert string s to nibbles (half-bytes)

    >>> bin_to_nibbles("")
    []
    >>> bin_to_nibbles("h")
    [6, 8]
    >>> bin_to_nibbles("he")
    [6, 8, 6, 5]
    >>> bin_to_nibbles("hello")
    [6, 8, 6, 5, 6, 12, 6, 12, 6, 15]
    """
def bin_to_nibbles(s: Any) -> object {
    res = [];
    for x in s {
        res += divmod(ord(x), 16);
    }
    return res;
}

"""
    Extract substring of letters for which predicate is True
    """
def parse_substring(allele: Any, pred: Any, max_len: Any = None) -> object {
    result = "";
    pos = 0;
    if (max_len is None) {
        max_len = len(allele);
    } else {
        max_len = min(max_len, len(allele));
    }
    while ((pos < max_len) and pred(allele[pos])) {
        result += allele[pos];
        pos += 1;
    }
    return (result, allele[pos:]);
}

"""
    Return true if the supplied edge is a cross-host edge according to the
    mpi nodes supplied.
    """
def is_cross_host(mpi_nodes: Any, `edge: Any) -> object {
    out_node_key = `edge[0][0];
    in_node_key = `edge[0][1];
    return (mpi_nodes[out_node_key]["host"] != mpi_nodes[in_node_key]["host"]);
}

"""Get the real value of the standard number.

    Args:
        std_num: The number you want to reduction.

    Returns:
        The real value of the number.
    """
def real_number(std_num: float) -> float {
    return (float(std_num) / 100000000);
}
